create extension if not exists pgcrypto;
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),name text not null,email text not null,company text not null,phone text,active_projects integer default 0,overdue_cash numeric default 0,monthly_revenue numeric default 0,payment_terms_days integer default 30,payment_pressure boolean default false,cash_exposure numeric default 0,priority text not null default 'Watch',source text not null default 'cashflow-audit',status text not null default 'new',consent_at timestamptz,follow_up_sent_at timestamptz);
create table if not exists public.lead_events(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),lead_id uuid not null references public.leads(id) on delete cascade,event_type text not null,metadata jsonb not null default '{}'::jsonb);
alter table public.leads enable row level security; alter table public.lead_events enable row level security; revoke all on public.leads from anon,authenticated; revoke all on public.lead_events from anon,authenticated;